// Independent, audit-friendly byte vector for the serverbound pack response
// documented by Mojang for Bedrock 1.26.60 / protocol 2225 / packet 0x08.
// This is deliberately NOT generated by bedrock-protocol, so comparing it
// against the bundled serializer detects schema, casing and list mistakes.
// The real transport still uses its normal authenticated reliable sender.
const variants=Object.freeze({
  refused:{selector:0,text:'Cancel'},
  send_packs:{selector:1,text:'Downloading'},
  have_all_packs:{selector:2,text:'DownloadingFinished'},
  completed:{selector:3,text:'ResourcePackStackFinished'}
})
function varuint(n){
  if(!Number.isSafeInteger(n)||n<0||n>0xffffffff)throw Error('Invalid protocol varuint')
  const out=[]
  do{let byte=n&127;n=Math.floor(n/128);if(n)byte|=128;out.push(byte)}while(n)
  return Buffer.from(out)
}
function string(value){
  const bytes=Buffer.from(value,'utf8')
  return Buffer.concat([varuint(bytes.length),bytes])
}
/** Official packet 8, oneOf variant tag, canonical response string,
 * then Downloading-only array of UUID_version strings. */
export function officialPackResponse2225(status,packIds=[]){
  const variant=variants[status]
  if(!variant)throw Error('Unknown 2225 resource-pack response')
  if(!Array.isArray(packIds)||packIds.length>64)throw Error('Invalid advertised pack count')
  if(status==='send_packs'&&!packIds.length)throw Error('Downloading needs server-advertised packs')
  if(status!=='send_packs'&&packIds.length)throw Error('Completion packets cannot contain pack IDs')
  const parts=[varuint(8),varuint(variant.selector),string(variant.text)]
  if(status==='send_packs'){
    parts.push(varuint(packIds.length))
    for(const id of packIds){
      if(typeof id!=='string'||!(/^[a-zA-Z0-9-]{1,80}_[0-9][a-zA-Z0-9_.-]{0,39}$/.test(id)))
        throw Error('Invalid advertised UUID_version pack identifier')
      parts.push(string(id))
    }
  }
  return Buffer.concat(parts)
}
export function assertOfficialPackResponse2225(frame,status,packIds=[]){
  const expected=officialPackResponse2225(status,packIds)
  if(!Buffer.isBuffer(frame)||!frame.equals(expected))
    throw Error('Bundled Bedrock serializer differs from Mojang 2225 packet 8 byte sequence')
  return {verified:true,byteLength:expected.length,variant:variants[status].selector,wireText:variants[status].text,packIdCount:packIds.length}
}
